const result = $input.first().json.data;
const plans = result.plans || [];

return plans.map((p, idx) => {
  const now = new Date();
  const schedDate = new Date(now.getTime() + (p.day_offset || (idx + 1)) * 86400000);
  schedDate.setHours(10, 30, 0, 0);

  return {
    json: {
      content_id: 'ZH-IDEA-' + Math.random().toString(36).substring(2, 9).toUpperCase(),
      topic: p.topic,
      platform: p.target_platform || 'LinkedIn',
      content_category: p.pillar || 'Educational',
      target_audience: p.target_audience || 'Indian SMEs & Founders',
      cta: p.primary_cta || 'Visit zethub.in',
      scheduled_at: schedDate.toISOString().replace('T', ' ').substring(0, 19),
      approval_status: 'DRAFT',
      publishing_status: 'IDEA',
      brief: p.brief || ''
    }
  };
});
